        ],
        "output_format": "png",
        "prompt": "{
    "image_concept": "A high-contrast, high-energy party snapshot with a freeze-frame aesthetic, capturing two young men in a dynamic, candid pose.",
    "effects_and_style": {
        "visual_style": "Freeze-frame snapshot effect, capturing a raw, high-intensity party moment in motion.",
        "lighting_and_camera": "Intense direct photo flash creating sharp shadows on the background, bright specular highlights, and a subtle camera shutter light-leak effect on the outer borders."
    },
    "composition": {
        "layout": "Two male subjects in a close, side-by-side foreground pose under a rustic ceiling.",
        "left_subject_pose": "Shirtless, standing confidently with his right arm draped over his partner's shoulder, facing forward.",
        "right_subject_pose": "Stands next to him, looking directly at the camera with a calm, self-assured, masculine expression."
    },
    "subject_1_shirtless_boyfriend": {
        "physique": "Shirtless, displaying a highly athletic, lean, and muscular torso with sharply defined six-pack abdominal muscles and chest.",
        "facial_features": {
            "gaze": "Direct, piercing look toward the lens.",
            "eyes": "Striking, clear blue-green eyes.",
            "eyebrows": "Defined, dark, groomed.",
            "nose": "Symmetrical, straight nose bridge.",
            "lips": "Natural pinkish, closed in a relaxed expression.",
            "jawline": "Sharp, clean-shaven jaw."
        },
        "hair": "Messy, textured dark brown curls on top with a clean undercut fade on the sides.",
        "jewelry": "A thin black cord necklace with a small geometric pendant resting on his bare collarbone."
    },
    "subject_2_white_haired_man": {
        "facial_features": {
            "expression": "A cool, confident, relaxed masculine expression. Mouth is closed in a neutral look, avoiding any puckering or kissy-face expressions.",
            "gaze": "Steady, self-assured gaze directly into the lens.",
            "eyes": "Dark brown eyes with natural, relaxed eyelids.",
            "skin_complexion": "Fair, smooth olive skin with realistic micro-pores and a subtle shadow of clean-shaven stubble."
        },
        "hair": {
            "color": "Vibrant, high-contrast dyed platinum-white hair.",
            "style": "Short, textured spiky crop on top, with a clean skin-fade undercut on the sides where natural dark hair is visible near the ears."
        },
        "apparel": {
            "description": "A sleek, masculine black nylon streetwear bomber jacket, partially zipped, showing clean lines and heavy-weight fabric texture."
        }
    },
    "background_environment": {
        "ceiling": "Rustic dark wood-panel ceiling with exposed beams, illuminated by a deep red and magenta ambient glow.",
        "decorations": "A vertical strand of warm orange fairy lights behind the subjects, rendering as soft, glowing golden bokeh circles.",
        "depth": "Shallow depth of field with heavily blurred background details, framing the two subjects in sharp focus."
    },
    "optimized_generation_prompt": "A raw, high-fidelity photo flash snapshot of two young men posing confidently side-by-side in a rustic room. On the left, a shirtless young man with a highly muscular six-pack torso, messy dark brown wavy curls, and striking blue-green eyes poses with his arm around his partner. On the right, a young man with textured, dyed platinum-white hair and a clean undercut fade looks directly into the camera with a cool, confident, relaxed masculine expression and a neutral mouth.. Capturing a dynamic freeze-frame snapshot aesthetic with an intense overexposed camera flash, sharp shadows cast on the dark background, and a warm magenta ambient glow on the wooden beamed ceiling. Hyper-realistic skin textures, shallow depth of field, 35mm lens style."
}",
